// \u51fd\u6570\u540d\uff0c\u8fd9\u91cc\u4e3a null \u56e0\u4e3a\u662f\u533f\u540d\u51fd\u6570\n      node.params,\n      body,\n      false, // generator\n      false // async\n    )\n\n    // \u66ff\u6362\u539f\u8282\u70b9\n    path.replaceWith(functionExpression)\n  },\n\n  // \u8bbf\u95ee\u6a21\u677f\u5b57\u7b26\u4e32\n  TemplateLiteral (path) {\n    const { expressions, quasis } = path.node\n\n    // \u5c06\u6a21\u677f\u5b57\u7b26\u4e32\u8f6c\u6362\u4e3a\u5b57\u7b26\u4e32\u62fc\u63a5\n    const strings = quasis.map(quasi => quasi.value.raw)\n    const nodes = []\n\n    strings.forEach((str, i) => {\n      nodes.push(t.stringLiteral(str))\n      if (expressions[i]) {\n        nodes.push(expressions[i])\n      }\n    })\n\n    // \u4f7f\u7528 + \u8fd0\u7b97\u7b26\u62fc\u63a5\u5b57\u7b26\u4e32\n    let current = nodes[0]\n    for (let i = 1; i < nodes.length; i++) {\n      current = t.binaryExpression('+', current, nodes[i])\n    }\n\n    path.replaceWith(current)\n  }\n})\n\n// 3. \u751f\u6210\uff08Generate\uff09\n// \u5c06\u8f6c\u6362\u540e\u7684 AST \u91cd\u65b0\u751f\u6210\u4ee3\u7801\nconst output = generate(ast, {}, sourceCode)\n\nconsole.log('\u8f6c\u6362\u524d\u7684\u4ee3\u7801\uff1a')\nconsole.log(sourceCode)\nconsole.log('\\n\u8f6c\u6362\u540e\u7684\u4ee3\u7801\uff1a')\nconsole.log(output.code)\n",r='{\n  "name": "babel-principle-demo",\n  "version": "1.0.0",\n  "description": "\u6f14\u793a Babel \u5de5\u4f5c\u539f\u7406\u7684\u4e09\u4e2a\u4e3b\u8981\u6b65\u9aa4",\n  "main": "index.js",\n  "scripts": {\n    "start": "node index.js"\n  },\n  "dependencies": {\n    "@babel/core": "^7.24.0",\n    "@babel/parser": "^7.24.0",\n    "@babel/traverse": "^7.24.0",\n    "@babel/generator": "^7.24.0",\n    "@babel/types": "^7.24.0"\n  }\n}\n',c="const fs = require('fs')\nconst path = require('path')\n\nmodule.exports = function (babel) {\n  return {\n    name: 'babel-plugin-todo-collector',\n\n    pre (state) {\n      console.log('\ud83d\ude80 Entering babel-plugin-todo-collector')\n      const options = state.opts || {}\n      this.todos = []\n      this.outputFile = options.outputFile || 'todo.md'\n      this.projectRoot = options.projectRoot || process.cwd()\n    },\n\n    visitor: {\n      Program: {\n        enter (path, state) {\n          console.log(`\ud83d\udcd1 Processing file: ${state.file.opts.filename}`)\n\n          const comments = path.container.comments || []\n          const filename = state.file.opts.filename\n\n          comments.forEach(comment => {\n            const todoMatch = comment.value.match(/TODO:?\\s*(.*)/i)\n            if (todoMatch) {\n              const todo = todoMatch[1].trim()\n              const { line, column } = comment.loc.start\n\n              this.todos.push({\n                content: todo,\n                file: filename,\n                line,\n                column\n              })\n            }\n          })\n        },\n\n        exit () {\n          console.log('\u2705 Finished processing file')\n        }\n      }\n    },\n\n    post (state) {\n      if (this.todos.length > 0) {\n        const markdown = this.todos.map(todo => {\n          const relativePath = path.relative(this.projectRoot, todo.file)\n          const fileName = path.basename(todo.file)\n          return `* [ ] ${todo.content}, \u8be6\u89c1 [${fileName}](${relativePath}#L${todo.line},${todo.column})`\n        }).join('\\n')\n\n        fs.writeFileSync(\n          path.join(process.cwd(), this.outputFile),\n          markdown,\n          'utf-8'\n        )\n\n        console.log(`\u2705 Collected ${this.todos.length} TODOs into ${this.outputFile}`)\n      }\n      console.log('\ud83d\udc4b Exiting babel-plugin-todo-collector')\n    }\n  }\n}\n",a="const babel = require('@babel/core')\nconst fs = require('fs')\nconst path = require('path')\nconst todoPlugin = require('./plugin.js')\n\nconst testCode = `\n// TODO: \u9700\u8981\u5b9e\u73b0\u767b\u5f55\u529f\u80fd\nfunction login() {\n  // TODO: \u6dfb\u52a0\u9a8c\u8bc1\u903b\u8f91\n  console.log('login');\n}\n\n/* TODO: \u5b9e\u73b0\u6ce8\u518c\u529f\u80fd */\nfunction register() {\n  console.log('register');\n}\n`\n\ndescribe('babel-plugin-todo-collector', () => {\n  beforeEach(() => {\n    // \u786e\u4fdd\u6bcf\u6b21\u6d4b\u8bd5\u524d\u5220\u9664\u5df2\u5b58\u5728\u7684 todo.md\n    const todoPath = path.join(process.cwd(), 'todo.md')\n    if (fs.existsSync(todoPath)) {\n      fs.unlinkSync(todoPath)\n    }\n  })\n\n  it('should collect todos and generate markdown file', () => {\n    babel.transform(testCode, {\n      filename: 'test.js',\n      plugins: [todoPlugin],\n      configFile: false, // \u7981\u7528 babel.config.js\n      babelrc: false // \u7981\u7528 .babelrc\n    })\n\n    const todoContent = fs.readFileSync(path.join(process.cwd(), 'todo.md'), 'utf-8')\n\n    // \u66f4\u8be6\u7ec6\u7684\u65ad\u8a00\n    expect(todoContent).toContain('[ ]')\n    expect(todoContent).toContain('test.js#L')\n    expect(todoContent).toContain('\u9700\u8981\u5b9e\u73b0\u767b\u5f55\u529f\u80fd')\n    expect(todoContent).toContain('\u6dfb\u52a0\u9a8c\u8bc1\u903b\u8f91')\n    expect(todoContent).toContain('\u5b9e\u73b0\u6ce8\u518c\u529f\u80fd')\n  })\n})\n",d='{\n  "name": "babel-plugin-todo-collector",\n  "version": "1.0.0",\n  "main": "src/index.js",\n  "dependencies": {\n    "@babel/cli": "^7.26.4",\n    "@babel/core": "^7.x"\n  },\n  "devDependencies": {\n    "jest": "^29.x"\n  },\n  "scripts": {\n    "test": "jest",\n    "build": "babel src.js --out-dir dist"\n  },\n  "babel": {\n    "plugins": [\n      "./plugin.js"\n    ]\n  }\n}',b={},p="babel\u2705",h={},u=[{value:"\u65e5\u5e38\u6709\u4f7f\u7528\u8fc7 babel \u4e48\uff0c\u7528\u5728\u54ea\u4e9b\u573a\u666f\uff1f",id:"p1-babel",level:2},{value:"babel \u662f\u5982\u4f55\u5de5\u4f5c\u7684\uff1f",id:"p0-babel-principle",level:2},{value:"\u5982\u4f55\u7f16\u5199 babel \u63d2\u4ef6",id:"p1-bable-plugin",level:2}];function x(n){const e={a:"a",admonition:"admonition",code:"cod